const d = $json;
const errors = [];
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const name = (d.full_name || "").trim();
const email = (d.email || "").trim().toLowerCase();
const message = (d.message || "").trim();
let phone = (d.phone || "").toString().trim();
const phoneDigits = phone.replace(/[^0-9]/g, "");

if (!name) errors.push("Missing name");
if (!message) errors.push("Missing message");
if (!email) errors.push("Missing email");
else if (!emailRe.test(email)) errors.push("Invalid email format");
if (phone && phoneDigits.length < 7) errors.push("Invalid phone number");

const emptyFields = ["full_name","email","message"].filter(f => !((d[f] || "").toString().trim()));
if (emptyFields.length >= 2) errors.push("Too many empty required fields");

const dupKey = (email + "|" + name.toLowerCase()).trim();

return {
  json: {
    ...d,
    full_name: name,
    email,
    phone,
    message,
    dedupe_key: dupKey,
    is_valid: errors.length === 0,
    validation_errors: errors.join("; "),
  },
};

