const raw = ($json.text || $json.output || "").toString();
let clean = raw.trim().replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
let obj = {};
try { obj = JSON.parse(clean); } catch (e) {
  const m = clean.match(/\{[\s\S]*\}/);
  if (m) { try { obj = JSON.parse(m[0]); } catch (_) {} }
}
let score = Number(obj.lead_score);
if (!Number.isFinite(score)) score = 0;
let temp = (obj.lead_temperature || "").toString();
if (!/^(hot|warm|cold)$/i.test(temp)) {
  temp = score >= 80 ? "Hot" : score >= 50 ? "Warm" : "Cold";
}
temp = temp.charAt(0).toUpperCase() + temp.slice(1).toLowerCase();
return { json: {
  lead_score: score,
  lead_temperature: temp,
  priority: obj.priority || "Medium",
  score_reason: obj.reason || "",
} };

