const engagement = Number($json.engagement_score || 0);
const base = Number($json.lead_score || 0);
const newScore = Math.min(100, base + engagement);
let temp = "Cold";
if (newScore >= 80) temp = "Hot";
else if (newScore >= 50) temp = "Warm";
return { json: { ...$json, recalculated_score: newScore, recalculated_temperature: temp } };

const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const norm = (v) => (v || "").toString().toLowerCase();
const total = rows.length;
const spam = rows.filter(r => norm(r.spam_classification) === "spam").length;
const valid = total - spam;
const hot = rows.filter(r => norm(r.lead_status).includes("hot")).length;
const warm = rows.filter(r => norm(r.lead_status).includes("warm")).length;
const cold = rows.filter(r => norm(r.lead_status).includes("cold")).length;
const responded = rows.filter(r => norm(r.lead_status).includes("respond") || norm(r.customer_replied) === "yes").length;
const converted = rows.filter(r => norm(r.converted) === "yes" || norm(r.lead_status).includes("convert")).length;
const followups = rows.reduce((a, r) => a + Number(r.followups_sent || 0), 0);
const conversionRate = total ? Math.round((converted / total) * 1000) / 10 : 0;
return [{ json: {
  report_date: $now.toISODate(),
  total_leads: total,
  valid_leads: valid,
  spam_leads: spam,
  hot_leads: hot,
  warm_leads: warm,
  cold_leads: cold,
  responded_leads: responded,
  converted_leads: converted,
  followups_sent: followups,
  conversion_rate: conversionRate,
} }];
